DECLARE @defaults TABLE(table_name sysname,column_name sysname,constraint_name sysname,definition nvarchar(100));
INSERT @defaults VALUES ('InventoryItem','count_frequency','DF_InventoryItem_CountFrequency','(''WEEKLY'')'),('InventoryItem','average_unit_cost','DF_InventoryItem_AverageUnitCost','((0))'),('GoodsReceipt','status','DF_GoodsReceipt_Status','(''DRAFT'')'),('GoodsReceipt','created_at','DF_GoodsReceipt_CreatedAt','(getdate())'),('StockCount','status','DF_StockCount_Status','(''DRAFT'')'),('StockCount','created_at','DF_StockCount_CreatedAt','(getdate())');
IF EXISTS(SELECT 1 FROM @defaults e LEFT JOIN sys.tables t ON t.name=e.table_name AND SCHEMA_NAME(t.schema_id)='dbo' LEFT JOIN sys.columns c ON c.object_id=t.object_id AND c.name=e.column_name LEFT JOIN sys.default_constraints d ON d.parent_object_id=t.object_id AND d.parent_column_id=c.column_id AND d.name=e.constraint_name WHERE d.object_id IS NULL OR LOWER(REPLACE(d.definition,' ',''))<>LOWER(e.definition)) THROW 51000, '053 default mismatch', 1;

