IF EXISTS(SELECT 1 FROM @fks e WHERE NOT EXISTS(SELECT 1 FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id=fk.object_id JOIN sys.tables pt ON pt.object_id=fk.parent_object_id JOIN sys.columns pc ON pc.object_id=pt.object_id AND pc.column_id=fkc.parent_column_id JOIN sys.tables rt ON rt.object_id=fk.referenced_object_id JOIN sys.columns rc ON rc.object_id=rt.object_id AND rc.column_id=fkc.referenced_column_id WHERE fk.name=e.name AND pt.name=e.parent_table AND pc.name=e.parent_column AND rt.name=e.referenced_table AND rc.name=e.referenced_column AND fk.is_disabled=0 AND fk.is_not_trusted=0)) THROW 51000, '053 foreign key missing or invalid', 1;

