IF EXISTS(SELECT 1 FROM @constraints e JOIN sys.tables t ON t.name=e.table_name AND SCHEMA_NAME(t.schema_id)='dbo' WHERE (e.type='P' AND NOT EXISTS(SELECT 1 FROM sys.key_constraints k WHERE k.parent_object_id=t.object_id AND k.name=e.name AND k.type='PK')) OR (e.type='U' AND NOT EXISTS(SELECT 1 FROM sys.key_constraints k WHERE k.parent_object_id=t.object_id AND k.name=e.name AND k.type='UQ')) OR (e.type='C' AND NOT EXISTS(SELECT 1 FROM sys.check_constraints c WHERE c.parent_object_id=t.object_id AND c.name=e.name AND c.is_disabled=0 AND c.is_not_trusted=0))) THROW 51000, '053 primary key, unique, or check constraint missing or invalid', 1;
DECLARE @checks TABLE(name sysname,definition nvarchar(1000));
INSERT @checks VALUES ('CK_InventoryItem_CountFrequency','[count_frequency]=''WEEKLY''OR[count_frequency]=''DAILY'''),('CK_InventoryItem_AverageUnitCost','[average_unit_cost]>=(0)'),('CK_GoodsReceipt_Status','[status]=''APPROVED''OR[status]=''DRAFT'''),('CK_GoodsReceipt_Approval','[status]=''DRAFT''AND[approved_by]ISNULLAND[approved_at]ISNULLOR[status]=''APPROVED''AND[approved_by]ISNOTNULLAND[approved_at]ISNOTNULL'),('CK_GoodsReceiptItem_Positive','[purchase_quantity]>(0)AND[conversion_factor]>(0)AND[base_quantity]>(0)AND[purchase_unit_price]>(0)AND[line_total]>(0)'),('CK_GoodsReceiptItem_Cost','[average_cost_before]ISNULLAND[average_cost_after]ISNULLOR[average_cost_before]>=(0)AND[average_cost_after]>=(0)'),('CK_StockCount_Frequency','[frequency]=''WEEKLY''OR[frequency]=''DAILY'''),('CK_StockCount_Status','[status]=''APPROVED''OR[status]=''DRAFT'''),('CK_StockCount_Approval','[status]=''DRAFT''AND[approved_by]ISNULLAND[approved_at]ISNULLOR[status]=''APPROVED''AND[approved_by]ISNOTNULLAND[approved_at]ISNOTNULL'),('CK_StockCountItem_Quantity','[theoretical_quantity]>=(0)AND[actual_quantity]ISNULLOR[actual_quantity]>=(0)'),('CK_StockCountItem_Cost','[unit_cost_snapshot]ISNULLOR[unit_cost_snapshot]>=(0)'),('CK_InventoryTransaction_Cost','[unit_cost_snapshot]ISNULLOR[unit_cost_snapshot]>=(0)AND[total_cost]ISNULLOR[total_cost]>=(0)');
IF EXISTS(SELECT 1 FROM @checks e JOIN sys.check_constraints c ON c.name=e.name WHERE REPLACE(REPLACE(REPLACE(c.definition,' ',''),'(',''),')','')<>REPLACE(REPLACE(e.definition,'(',''),')','')) THROW 51000, '053 check definition mismatch', 1;
DECLARE @keys TABLE(table_name sysname,name sysname,column_1 sysname,column_2 sysname NULL);
INSERT @keys VALUES ('GoodsReceipt','PK_GoodsReceipt','goods_receipt_id',NULL),('GoodsReceiptItem','PK_GoodsReceiptItem','goods_receipt_item_id',NULL),('StockCount','PK_StockCount','stock_count_id',NULL),('StockCountItem','PK_StockCountItem','stock_count_item_id',NULL),('InventoryItem','UQ_InventoryItem_Code','inventory_code',NULL),('GoodsReceiptItem','UQ_GoodsReceiptItem_ReceiptItem','goods_receipt_id','inventory_item_id'),('StockCountItem','UQ_StockCountItem_CountItem','stock_count_id','inventory_item_id');
IF EXISTS(SELECT 1 FROM @keys e WHERE NOT EXISTS(SELECT 1 FROM sys.key_constraints k JOIN sys.tables t ON t.object_id=k.parent_object_id JOIN sys.index_columns ic1 ON ic1.object_id=t.object_id AND ic1.index_id=k.unique_index_id AND ic1.key_ordinal=1 JOIN sys.columns c1 ON c1.object_id=t.object_id AND c1.column_id=ic1.column_id LEFT JOIN sys.index_columns ic2 ON ic2.object_id=t.object_id AND ic2.index_id=k.unique_index_id AND ic2.key_ordinal=2 LEFT JOIN sys.columns c2 ON c2.object_id=t.object_id AND c2.column_id=ic2.column_id WHERE t.name=e.table_name AND SCHEMA_NAME(t.schema_id)='dbo' AND k.name=e.name AND c1.name=e.column_1 AND ISNULL(c2.name,'')=ISNULL(e.column_2,''))) THROW 51000, '053 primary key or unique columns invalid', 1;

IF NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic1 ON ic1.object_id=i.object_id AND ic1.index_id=i.index_id AND ic1.key_ordinal=1 JOIN sys.columns c1 ON c1.object_id=i.object_id AND c1.column_id=ic1.column_id JOIN sys.index_columns ic2 ON ic2.object_id=i.object_id AND ic2.index_id=i.index_id AND ic2.key_ordinal=2 JOIN sys.columns c2 ON c2.object_id=i.object_id AND c2.column_id=ic2.column_id WHERE i.object_id=OBJECT_ID(N'dbo.GoodsReceipt') AND i.name=N'IX_GoodsReceipt_StatusReceived' AND c1.name='status' AND c2.name='received_at' AND ic2.is_descending_key=1) THROW 51000, '053 goods receipt index invalid', 1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic1 ON ic1.object_id=i.object_id AND ic1.index_id=i.index_id AND ic1.key_ordinal=1 JOIN sys.columns c1 ON c1.object_id=i.object_id AND c1.column_id=ic1.column_id JOIN sys.index_columns ic2 ON ic2.object_id=i.object_id AND ic2.index_id=i.index_id AND ic2.key_ordinal=2 JOIN sys.columns c2 ON c2.object_id=i.object_id AND c2.column_id=ic2.column_id WHERE i.object_id=OBJECT_ID(N'dbo.StockCount') AND i.name=N'IX_StockCount_StatusDate' AND c1.name='status' AND c2.name='count_date' AND ic2.is_descending_key=1) THROW 51000, '053 stock count index invalid', 1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id AND ic.key_ordinal=1 JOIN sys.columns c ON c.object_id=i.object_id AND c.column_id=ic.column_id WHERE i.object_id=OBJECT_ID(N'dbo.InventoryTransaction') AND i.name=N'IX_InventoryTransaction_GoodsReceipt' AND c.name='goods_receipt_id' AND REPLACE(REPLACE(REPLACE(i.filter_definition,' ',''),'(',''),')','')='[goods_receipt_id]ISNOTNULL') THROW 51000, '053 goods receipt filtered index invalid', 1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id AND ic.key_ordinal=1 JOIN sys.columns c ON c.object_id=i.object_id AND c.column_id=ic.column_id WHERE i.object_id=OBJECT_ID(N'dbo.InventoryTransaction') AND i.name=N'IX_InventoryTransaction_StockCount' AND c.name='stock_count_id' AND REPLACE(REPLACE(REPLACE(i.filter_definition,' ',''),'(',''),')','')='[stock_count_id]ISNOTNULL') THROW 51000, '053 stock count filtered index invalid', 1;

IF EXISTS(SELECT 1 FROM dbo.InventoryItem WHERE inventory_code IS NULL OR inventory_code='' OR count_frequency NOT IN('DAILY','WEEKLY') OR average_unit_cost<0) THROW 51000, '053 inventory data invalid', 1;
IF EXISTS(SELECT inventory_item_id FROM dbo.InventoryTransaction WHERE reference_type='MIGRATION' AND reference_id='053' GROUP BY inventory_item_id HAVING COUNT_BIG(*)>1) OR EXISTS(SELECT 1 FROM dbo.InventoryTransaction WHERE reference_type='MIGRATION' AND reference_id='053' AND (transaction_type<>'ADJUSTMENT' OR quantity_before<>0 OR quantity_after<>quantity OR unit_cost_snapshot<>0 OR total_cost<>0)) THROW 51000, '053 opening balance ledger invalid', 1;
PRINT '053 validation passed';
